//go:build !wasm

package command_test

import (
	"encoding/json"
	"fmt"
	"net"
	"os"
	"path/filepath"
	"testing"

	"github.com/xtls/xray-core/core"
	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/protobuf/proto"
)

// The optional input is generated by the panel's actual TypeScript compiler,
// not a hand-maintained Go approximation of its output. Test ports are replaced
// with ephemeral loopback sockets so it cannot contact an external service.
func TestPanelCompiledProfilesKeepIndependentRoutesAndSessions(t *testing.T) {
	fixturePath := os.Getenv("REMNACUST_PORT_PLAN_FIXTURE")
	if fixturePath == "" {
		t.Skip("Generate the panel profile-port-plan fixture and set REMNACUST_PORT_PLAN_FIXTURE")
	}
	info, err := os.Stat(fixturePath)
	if err != nil || !info.Mode().IsRegular() || info.Size() > 4*1024*1024 {
		t.Fatal("invalid compiled profile fixture", err)
	}
	encoded, err := os.ReadFile(fixturePath)
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Version     int                    `json:"version"`
		Initial     map[string]interface{} `json:"initial"`
		Updated     map[string]interface{} `json:"updated"`
		Conflicting map[string]interface{} `json:"conflicting"`
		Removed     map[string]interface{} `json:"removed"`
	}
	if err := json.Unmarshal(encoded, &fixture); err != nil || fixture.Version != 1 {
		t.Fatal("invalid compiled profile fixture version", err)
	}
	destinationA, destinationB, destinationC := runtimeEcho(t, "A:"), runtimeEcho(t, "B:"), runtimeEcho(t, "C:")
	apiPort, portA, portB := availableRuntimePort(t), availableRuntimePort(t), availableRuntimePort(t)
	occupied, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer occupied.Close()
	ports := map[int]int{48101: portA, 48102: portB, 48103: occupied.Addr().(*net.TCPAddr).Port}
	redirects := map[string]string{
		"127.0.0.1:48201": fmt.Sprint("127.0.0.1:", destinationA),
		"127.0.0.1:48202": fmt.Sprint("127.0.0.1:", destinationB),
		"127.0.0.1:48203": fmt.Sprint("127.0.0.1:", destinationC),
	}
	var replace func(interface{})
	replace = func(value interface{}) {
		switch v := value.(type) {
		case map[string]interface{}:
			for key, child := range v {
				if key == "port" {
					if port, ok := child.(float64); ok {
						if replacement, found := ports[int(port)]; found {
							v[key] = replacement
						}
					}
				}
				if key == "redirect" {
					if address, ok := child.(string); ok {
						if replacement, found := redirects[address]; found {
							v[key] = replacement
						}
					}
				}
				replace(child)
			}
		case []interface{}:
			for _, child := range v {
				replace(child)
			}
		}
	}
	build := func(document map[string]interface{}) *core.Config {
		t.Helper()
		if document == nil {
			t.Fatal("missing compiled fixture document")
		}
		replace(document)
		document["api"] = map[string]interface{}{"tag": "PRIVATE_API", "listen": fmt.Sprint("127.0.0.1:", apiPort), "services": []string{"HandlerService"}}
		return runtimeBuildJSON(t, document)
	}
	config, next, failed, removed := build(fixture.Initial), build(fixture.Updated), build(fixture.Conflicting), build(fixture.Removed)
	if len(config.Inbound) != 2 || len(config.Outbound) != 4 {
		t.Fatal("compiler exposed an unselected inbound or lost a profile")
	}
	server, err := core.New(config)
	if err != nil {
		t.Fatal(err)
	}
	checkpoint := filepath.Join(t.TempDir(), "private", "checkpoint.pb")
	server.SetRuntimeJournal(checkpoint)
	if err := server.Start(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { server.Close() })
	control, err := grpc.NewClient(fmt.Sprint("127.0.0.1:", apiPort), grpc.WithTransportCredentials(insecure.NewCredentials()))
	if err != nil {
		t.Fatal(err)
	}
	defer control.Close()
	originalA, originalB := runtimeClient(t, portA, destinationA), runtimeClient(t, portB, destinationA)
	runtimePing(t, originalA, "A:", true)
	runtimePing(t, originalB, "B:", true)
	if err := runtimeApply(control, next, runtimeInspect(t, control)); err != nil {
		t.Fatal(err)
	}
	runtimePing(t, originalA, "A:", false)
	runtimePing(t, originalB, "B:", false)
	freshA, freshB := runtimeClient(t, portA, destinationA), runtimeClient(t, portB, destinationA)
	runtimePing(t, freshA, "C:", true)
	runtimePing(t, freshB, "B:", true)
	saved, err := core.LoadRuntimeJournal(checkpoint)
	if err != nil || !proto.Equal(saved, next) {
		t.Fatal("applied compiled plan was not persisted", err)
	}
	before := runtimeInspect(t, control)
	if err := runtimeApply(control, failed, before); err == nil {
		t.Fatal("a conflicting compiled port was acknowledged")
	}
	if runtimeInspect(t, control) != before {
		t.Fatal("a failed compiled plan replaced the running revision")
	}
	runtimePing(t, originalA, "A:", false)
	runtimePing(t, freshA, "C:", false)
	runtimePing(t, originalB, "B:", false)
	runtimePing(t, freshB, "B:", false)
	if err := runtimeApply(control, removed, runtimeInspect(t, control)); err != nil {
		t.Fatal(err)
	}
	runtimePing(t, originalA, "A:", false)
	runtimePing(t, freshA, "C:", false)
	runtimePing(t, freshB, "B:", false)
	runtimePing(t, runtimeClient(t, portB, destinationA), "B:", true)
}
